-- Run this once in the Supabase SQL editor for project ucvsnxexmvxpccyatmmk.
--
-- Moves engine build presets off static data in js/engineBuilder.js into a
-- real table, so Joanna can add/edit presets herself as she learns more real
-- builds, instead of asking for a code change every time (catalogue.html/
-- services.html's own "admin edits via the app, not SQL" pattern).
--
-- `key` is the stable identifier already saved on real jobs/engines --
-- job_legs.engine_spec and stored_engines.engine_spec both store
-- { valvetrain, configuration, style } with style = this key (sql/060, 062).
-- Never change an existing key once jobs may reference it; retire via
-- `active`, same convention as every other entity in this app.
--
-- `parts` holds the 11 build slots (block, crank, rod, piston, rings,
-- bearings, head, cam, tappet, spring, timing) exactly as js/engineBuilder.js
-- used them -- some are a single material name, some an ordered array of
-- fallbacks (first one the catalogue actually has for that engine wins).
-- `engine_type_pick`/`engine_type_reasons`/`engine_type_also` are the
-- matching ENGINE_TYPE_ADVICE entry (recommended valvetrain + why, plus
-- alternatives with their trade-off).

create table if not exists engine_style_profiles (
  id uuid primary key default gen_random_uuid(),
  key text not null unique,
  label text not null,
  hint text,
  sort_order integer not null default 0,
  active boolean not null default true,
  parts jsonb not null default '{}'::jsonb,
  engine_type_pick text,
  engine_type_reasons text[] not null default '{}',
  engine_type_also jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references mechanic_employees(id)
);

drop trigger if exists set_engine_style_profiles_updated_at on engine_style_profiles;
create trigger set_engine_style_profiles_updated_at before update on engine_style_profiles
  for each row execute function set_updated_at();

alter table engine_style_profiles enable row level security;
drop policy if exists "authenticated select engine_style_profiles" on engine_style_profiles;
create policy "authenticated select engine_style_profiles" on engine_style_profiles
  for select to authenticated using (true);
drop policy if exists "services insert engine_style_profiles" on engine_style_profiles;
create policy "services insert engine_style_profiles" on engine_style_profiles
  for insert to authenticated with check (has_area_permission('services'));
drop policy if exists "services update engine_style_profiles" on engine_style_profiles;
create policy "services update engine_style_profiles" on engine_style_profiles
  for update to authenticated using (has_area_permission('services')) with check (has_area_permission('services'));
grant select, insert, update on engine_style_profiles to authenticated;

-- Seed: the exact data that was live in js/engineBuilder.js's
-- ENGINE_STYLE_PROFILES/ENGINE_TYPE_ADVICE -- extracted programmatically from
-- the real file (Node eval of the literal, not retyped), so this is
-- byte-for-byte what was shipping, not a re-derivation.
insert into engine_style_profiles
  (key, label, hint, sort_order, parts, engine_type_pick, engine_type_reasons, engine_type_also)
values
  ('economy', 'Economy', 'Cheapest sensible parts for a reliable daily engine: cast iron, cast aluminium pistons, mild cam.', 0, '{"block": ["Cast Iron", "Cast Aluminum"], "crank": "Cast", "rod": ["I-Beam Powder Metal", "I-Beam Cast Steel"], "piston": ["Flat Top Cast Aluminum"], "rings": "Cast Iron (Standard) Ring Pack", "bearings": "Aluminum-Tin", "head": ["Factory Cast Iron", "Factory Cast Aluminum"], "cam": "Stock/Mild Camshaft", "tappet": "Hydraulic Flat Tappet Set", "spring": "Cast Steel", "timing": "Timing Belt Kit", "plugs": "Copper Standard Spark Plug"}'::jsonb, 'SOHC', '{"One camshaft per bank and fewer valves: fewer parts to buy and fewer to wear out.","Pulls well at low revs, which is where an everyday car spends its time.","The cheapest overhead-cam engine to build and service."}', '{"OHV": "Even simpler and cheaper, if top-end power doesn''t matter."}'::jsonb),
  ('comfort', 'Comfort', 'Smooth, quiet and long-lasting: light aluminium engine, mild cam, self-adjusting valvetrain.', 1, '{"block": ["Cast Aluminum", "Cast Iron"], "crank": "Cast", "rod": ["I-Beam Powder Metal", "I-Beam Forged Steel"], "piston": ["Flat Top Cast Aluminum"], "rings": "Cast Iron (Standard) Ring Pack", "bearings": "Aluminum-Tin", "head": ["Factory Cast Aluminum", "Factory Cast Iron"], "cam": "Stock/Mild Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Forged Steel", "timing": "Timing Belt Kit", "plugs": "Iridium Spark Plug"}'::jsonb, 'OHV', '{"Big, relaxed torque low down: smooth and quiet without needing revs.","Compact pushrod design with a self-adjusting hydraulic valvetrain.","The classic luxury-cruiser choice, like the big pushrod V8s."}', '{"DOHC": "More refined at higher revs, at a higher build cost."}'::jsonb),
  ('street', 'Street', 'Balanced everyday performance: forged crank and pistons, ported heads, street cam.', 2, '{"block": ["Cast Aluminum", "Cast Iron"], "crank": "Forged", "rod": ["I-Beam Forged Steel", "H-Beam Forged Steel"], "piston": ["Flat Top Forged Aluminum", "Flat Top Cast Aluminum"], "rings": "Steel Performance Ring Pack", "bearings": "Aluminum-Tin", "head": ["Ported & Polished Cast Aluminum"], "cam": "Street Perf Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Forged Steel", "timing": "Timing Chain Kit", "plugs": "Platinum Spark Plug"}'::jsonb, 'DOHC', '{"Four valves per cylinder, so it breathes well across the whole rev range.","Revs freely for fun on the road but stays easy-going in traffic.","The modern all-rounder that most performance road cars use."}', '{"SOHC": "A cheaper build that still revs well."}'::jsonb),
  ('performance', 'Performance', 'Strong all-round power that still lasts: forged internals, high-compression domed pistons, naturally aspirated.', 3, '{"block": ["Cast Aluminum", "Compacted Graphite Iron", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Forged Steel"], "piston": ["Domed Forged Aluminum"], "rings": "Steel Performance Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Aluminum", "Ported & Polished Cast Aluminum"], "cam": "Performance Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Chain Kit", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"The highest rev ceiling and the most aggressive cams we can fit.","The best airflow, so more power from the same size engine.","Separate intake and exhaust cams give a strong, wide powerband."}', '{"Rotary": "Very light, smooth and loves revs, but thirstier, and the apex seals need looking after."}'::jsonb),
  ('sports_durable', 'Sports Durable', 'High horsepower that still takes abuse: aluminium block for weight, forged steel rods/pistons/head for toughness under boost. Splits the difference between Performance and Durability.', 4, '{"block": ["Cast Aluminum", "Compacted Graphite Iron", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Forged Steel", "I-Beam Forged Steel"], "piston": ["Dished Forged Steel", "Dished Cast Steel"], "rings": "Steel Performance Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Steel", "Ported & Polished Forged Aluminum"], "cam": "Performance Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Forged Steel", "timing": "Timing Chain Kit", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"Four valves per cylinder for strong top-end power, matching this build''s Performance camshaft.","Handles the extra airflow a boosted, high-output engine needs.","Pairs with the self-adjusting hydraulic roller valvetrain, so it stays low-maintenance despite the power."}', '{"SOHC": "A simpler, cheaper build that still takes the same durable internals, for a bit less top end."}'::jsonb),
  ('durability', 'Durability', 'Built to last: CGI block, forged steel internals, heavy-duty bearings, mild cam and gear-driven timing.', 5, '{"block": ["Compacted Graphite Iron", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Forged Steel", "I-Beam Forged Steel"], "piston": ["Flat Top Forged Steel"], "rings": "Steel Performance Ring Pack", "bearings": "Tri-Metal", "head": ["Factory Cast Iron", "Factory Cast Aluminum"], "cam": "Stock/Mild Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Gears", "plugs": "Iridium Spark Plug"}'::jsonb, 'OHV', '{"The fewest moving parts in the top end, so less to go wrong.","Low-revving and unstressed, so everything lasts longer.","Simple to inspect and repair."}', '{"SOHC": "Still simple, with a bit more top-end power."}'::jsonb),
  ('heavy_machinery', 'Heavy Machinery', 'Low-revving torque for hauling and work vehicles: CGI/iron, forged steel pistons, torque cam, gear timing.', 6, '{"block": ["Compacted Graphite Iron", "Cast Iron"], "crank": "Forged", "rod": ["I-Beam Forged Steel", "H-Beam Forged Steel"], "piston": ["Flat Top Forged Steel"], "rings": "Steel Performance Ring Pack", "bearings": "Tri-Metal", "head": ["Factory Cast Iron"], "cam": "Torque/Tow Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Gears", "plugs": "Iridium Spark Plug"}'::jsonb, 'OHV', '{"Maximum low-rpm torque for pulling heavy loads.","Rugged and compact: the go-to for trucks and work vehicles.","Cheap to keep running."}', '{"SOHC": "A little more power up top, still simple."}'::jsonb),
  ('fleet', 'Emergency / Fleet', 'Huge mileage at sustained high revs (ambulances, police, taxis): light forged internals, heavy-duty bearings, torque cam, gear timing. Best on a DOHC with plenty of cylinders.', 7, '{"block": ["Compacted Graphite Iron", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Forged Steel", "I-Beam Forged Steel"], "piston": ["Flat Top Forged Aluminum", "Flat Top Cast Aluminum"], "rings": "Moly-Coated Race Ring Pack", "bearings": "Tri-Metal", "head": ["Factory Cast Aluminum", "Factory Cast Iron"], "cam": "Torque/Tow Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Gears", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"Holds sustained high revs without valve float: four light valves per cylinder instead of two heavy ones.","Runs cooler and more efficiently at constant speed, so it lasts for big mileage.","Pairs with the heavy-duty bearings and gear timing in this build."}', '{"SOHC": "Fewer parts to service, if the vehicle rarely runs at high revs."}'::jsonb),
  ('offroad', 'Off-Road', 'Tough, torquey and forgiving: iron block, forged internals, heavy-duty bearings, torque cam.', 8, '{"block": ["Cast Iron", "Compacted Graphite Iron"], "crank": "Forged", "rod": ["H-Beam Forged Steel"], "piston": ["Flat Top Forged Aluminum"], "rings": "Steel Performance Ring Pack", "bearings": "Tri-Metal", "head": ["Factory Cast Aluminum", "Factory Cast Iron"], "cam": "Torque/Tow Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Forged Steel", "timing": "Timing Chain Kit", "plugs": "Platinum Spark Plug"}'::jsonb, 'OHV', '{"Strong torque right off idle for crawling and climbing.","Compact and simple, so easy to fix far from a workshop.","Copes with water, mud and abuse."}', '{"SOHC": "A bit more top-end for faster trails."}'::jsonb),
  ('rally', 'Rally', 'Boosted and abused for whole stages: strong block, forged internals, broad-powerband cam, reliable hydraulic valvetrain.', 9, '{"block": ["Compacted Graphite Iron", "Cast Aluminum", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Billet Steel", "H-Beam Forged Steel"], "piston": ["Dished Forged Aluminum"], "rings": "Moly-Coated Race Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Aluminum"], "cam": "Performance Camshaft", "tappet": "Hydraulic Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Chain Kit", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"Responsive, high-revving power out of every corner.","Handles boost and long stages at full throttle.","What real rally engines use: compact four-valve turbo engines."}', '{"SOHC": "A tougher, simpler option on a budget."}'::jsonb),
  ('drift', 'Drift', 'Sustained high revs under boost: strong block, billet steel rods, forged pistons, race valvetrain.', 10, '{"block": ["Compacted Graphite Iron", "Cast Aluminum", "Cast Iron"], "crank": "Forged", "rod": ["H-Beam Billet Steel", "H-Beam Forged Steel"], "piston": ["Dished Forged Aluminum"], "rings": "Moly-Coated Race Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Aluminum"], "cam": "Race Camshaft", "tappet": "Solid Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Chain Kit", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"Holds high revs through long slides without running out of breath.","Instant throttle response for controlling the angle.","Takes the race cams and valvetrain this build uses."}', '{"Rotary": "Light, revs very high and a drift icon, but the apex seals wear under sustained abuse.", "OHV": "Big pushrod V8 torque for easy smoke, but we can only fit up to a street cam."}'::jsonb),
  ('drag', 'Drag', 'Maximum power in short bursts under big boost: billet block and crank, aluminium rods, billet pistons.', 11, '{"block": ["Billet Aluminum", "Compacted Graphite Iron", "Cast Iron"], "crank": "Billet", "rod": ["H-Beam Billet Aluminum", "H-Beam Forged Aluminum"], "piston": ["Dished Billet Aluminum", "Dished Forged Aluminum"], "rings": "Moly-Coated Race Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Aluminum"], "cam": "Race Camshaft", "tappet": "Solid Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Gears", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"Takes the most aggressive cams and the solid-roller valvetrain we offer.","Moves the most air at high revs, which is what big boost needs.","The highest power potential for short, all-out runs."}', '{"OHV": "The old-school pushrod V8: huge torque and compact, but limited to a street cam in our builds."}'::jsonb),
  ('race', 'Race', 'Lightest, fastest parts regardless of longevity: billet aluminium, titanium rods, race valvetrain.', 12, '{"block": ["Billet Aluminum", "Cast Aluminum", "Cast Iron"], "crank": "Billet", "rod": ["H-Beam Titanium", "H-Beam Billet Steel"], "piston": ["Dished Billet Aluminum", "Dished Forged Aluminum"], "rings": "Moly-Coated Race Ring Pack", "bearings": "Bi-Metal Race", "head": ["Ported & Polished Forged Aluminum"], "cam": "Race Camshaft", "tappet": "Solid Roller Tappet Set", "spring": "Billet Steel", "timing": "Timing Gears", "plugs": "Iridium Spark Plug"}'::jsonb, 'DOHC', '{"The highest rpm and most aggressive valvetrain: the most power per litre.","Lightweight valve gear for fast, precise response.","The standard in modern motorsport."}', '{"Rotary": "Tiny, light and smooth at high revs (it has won Le Mans), but the apex seals need frequent care."}'::jsonb)

on conflict (key) do nothing;
